<div class="row g8 mut sm"><a href="<?= sl_route('MessageLogs') ?>">Message Logs</a><i class="ic ic-sm i-right" aria-hidden="true"></i><span style="color:var(--ink)">New message</span></div>
<div class="sl-head"><div><h1 class="sl-title">Send a message</h1><p class="sl-lede">Reminders, pickup codes and updates by WhatsApp, SMS or e-mail</p></div><div class="row g8 wrap"><a class="sl-btn ghost" href="<?= sl_route('NotificationCenter') ?>"><i class="ic ic-sm i-file" aria-hidden="true"></i>Templates</a></div></div>
<form class="split" id="cm-form"><div class="a col g16"><section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">New message</h2></div>
<div class="sl-field"><span class="sl-lab">To</span><div class="row g6 wrap" id="cm-to" style="padding:6px;border:1px solid var(--line-2);border-radius:12px;background:var(--field);min-height:44px"><input id="cm-q" placeholder="Type a name, phone or locker" aria-label="Find a customer" style="border:0;background:transparent;flex:1;min-width:180px;font:inherit;outline:0"></div><div class="col" id="cm-sug" style="position:relative"></div></div>
<div class="grid cols2" style="gap:12px"><label class="sl-field"><span class="sl-lab">Or a segment</span><span class="sl-sel native"><select name="segment" id="cm-seg"><option value="">— none —</option><?php foreach ($d['segments'] as $s): ?><option value="<?= h($s['k']) ?>" <?= $s['k'] === $d['segment'] ? 'selected' : '' ?>><?= h($s['label']) ?> (<?= (int) $s['n'] ?>)</option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label><label class="sl-field"><span class="sl-lab">Or paste e-mails / phones</span><input class="sl-in" name="list" id="cm-list" placeholder="ama@mail.com, 024 551 0921"></label></div>
<div class="sl-field"><span class="sl-lab">Send by</span><div class="sl-seg boxed" id="cm-ch"><?php foreach (['whatsapp' => 'WhatsApp', 'sms' => 'SMS', 'email' => 'E-mail'] as $k => $l): ?><button type="button" class="<?= $k === $d['channel'] ? 'on' : '' ?>" data-v="<?= $k ?>"><?= $l ?><?= $d['health'][$k]['ok'] ? '' : ' ·' ?></button><?php endforeach; ?></div><span class="sl-hint" id="cm-chnote"></span></div>
<label class="sl-field"><span class="sl-lab">Template</span><span class="sl-sel native"><select id="cm-tpl"><option value="">Write my own</option></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label>
<label class="sl-field" id="cm-subj-f"><span class="sl-lab">Subject</span><input class="sl-in" name="subject" id="cm-subj" placeholder="Your parcel update"></label>
<label class="sl-field"><span class="sl-lab">Message</span><textarea class="np-ta" name="message" id="cm-msg">Hi [FIRST_NAME], </textarea></label>
<div class="row g6 wrap"><?php foreach (['[FIRST_NAME]', '[USERNAME]', '[SITE_NAME]', '[URL]'] as $v): ?><button type="button" class="np-chip" style="padding-right:10px" data-cm-var="<?= h($v) ?>"><?= h($v) ?></button><?php endforeach; ?></div>
<span class="mut sm">[FIRST_NAME] and [USERNAME] are filled in per customer by the WhatsApp and e-mail templates. Messages are written to Message Logs.</span>
<div class="row g8 wrap"><button class="sl-btn" type="submit" id="cm-send"><i class="ic ic-sm i-send" aria-hidden="true"></i><span>Send</span></button><button class="sl-btn ghost" type="button" id="cm-test">Send test to me</button></div>
<div class="col g6" id="cm-prog" hidden><div class="bc-bar" style="height:6px;border-radius:4px;background:var(--line);overflow:hidden"><i style="display:block;height:100%;width:0;background:var(--ink)"></i></div><span class="sm" id="cm-progt"></span><a class="sm fw5" href="<?= sl_route('MessageLogs') ?>">Open in message logs →</a></div>
</section></div>
<aside class="b col g16"><span class="up">Preview</span><div class="ph wa" style="align-self:center" id="cm-ph"><div class="ph-sc"><div class="ph-st"><span><?= date('H:i') ?></span><span class="ph-ic" aria-hidden="true"><i class="sig"><b></b><b></b><b></b><b></b></i><i class="wifi"></i><i class="bat"><b></b></i></span></div><div class="ph-hd"><span class="ph-av"><?= h(sl_initials($d['sample']['name'])) ?></span><span class="col grow"><span><?= h($d['sample']['name']) ?></span><span style="font:400 13px Figtree;color:#6B6A65" id="cm-via">via <?= h($site) ?></span></span></div>
<div class="ph-bd"><span class="ph-day">Today</span><div class="bub"><span class="hd" id="cm-pvs"></span><span id="cm-pvb" style="white-space:pre-line"></span><span class="tm"><?= date('H:i') ?> ✓✓</span></div></div>
<div class="ph-in"><i class="ic ic-sm i-plus" aria-hidden="true" style="color:#888"></i><span>Message</span><span class="mic"><i class="ic ic-sm i-send" aria-hidden="true"></i></span></div></div></div><section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Cost</h2></div><div class="sl-kv"><div><span id="cm-costl">Pick recipients</span><span id="cm-cost">—</span></div><div><span>Rates from</span><span><a href="<?= sl_route('MessageCosts') ?>#unit-costs">Message costs</a></span></div></div></section></aside></form>
<script>
(function(){
  var TPL = <?= json_encode($d['templates'], JSON_HEX_TAG) ?>, H = <?= json_encode(array_map(fn($x) => ['ok' => $x['ok'], 'state' => $x['state']], $d['health'])) ?>, sample = <?= json_encode($d['sample'], JSON_HEX_TAG) ?>, site = <?= json_encode($site) ?>;
  var picked = <?= json_encode($d['pre'], JSON_HEX_TAG) ?>, ch = <?= json_encode($d['channel']) ?>, $ = function(s){ return document.getElementById(s); };
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function chips(){ document.querySelectorAll('#cm-to .np-chip').forEach(function(c){ c.remove(); }); picked.forEach(function(p, i){ var s = document.createElement('span'); s.className = 'np-chip'; s.innerHTML = esc(p.name) + '<button type="button" data-cm-rm="' + i + '" aria-label="Remove" style="border:0;background:none;cursor:pointer"><i class="ic ic-sm i-x" aria-hidden="true"></i></button>'; $('cm-to').insertBefore(s, $('cm-q')); }); estimate(); }
  function fill(t){ return t.replace(/\[FIRST_NAME\]/g, sample.first).replace(/\[USERNAME\]|\[NAME\]/g, sample.name).replace(/\[SITE_NAME\]/g, site).replace(/\[URL\]/g, location.origin); }
  function prev(){ $('cm-pvb').textContent = fill($('cm-msg').value); $('cm-pvs').textContent = ch === 'sms' ? '' : fill($('cm-subj').value); $('cm-ph').className = 'ph ' + (ch === 'whatsapp' ? 'wa' : ch === 'sms' ? 'sms' : 'em'); $('cm-via').textContent = 'via ' + site + ' · ' + {whatsapp:'WhatsApp', sms:'SMS', email:'E-mail'}[ch]; }
  function tpls(){ var s = $('cm-tpl'); s.innerHTML = '<option value="">Write my own</option>' + (TPL[ch] || []).map(function(t, i){ return '<option value="' + i + '">' + esc(t.name) + '</option>'; }).join(''); $('cm-subj-f').style.display = ch === 'sms' ? 'none' : ''; $('cm-chnote').textContent = H[ch].ok ? '' : 'Channel status: ' + H[ch].state + ' — messages will be logged as failed or skipped.'; }
  function data(op){ return { op: op, channel: ch, ids: picked.map(function(p){ return p.id; }).join(','), segment: $('cm-seg').value, list: $('cm-list').value, subject: $('cm-subj').value, message: $('cm-msg').value }; }
  var et; function estimate(){ clearTimeout(et); et = setTimeout(function(){ SL.post('<?= $ajax ?>', data('estimate')).then(function(j){ if (!j.success) return; $('cm-send').querySelector('span').textContent = 'Send to ' + j.reach + ' ' + (j.reach === 1 ? 'person' : 'people'); $('cm-costl').textContent = j.reach + ' ' + {whatsapp:'WhatsApp messages', sms:'SMS', email:'e-mails'}[ch] + ' × ' + (j.currency || '') + ' ' + j.unit; $('cm-cost').textContent = (j.currency || '') + ' ' + j.cost.toFixed(3); }); }, 250); }
  var st; $('cm-q').addEventListener('input', function(){ var q = this.value; clearTimeout(st); st = setTimeout(function(){ SL.post('<?= $ajax ?>', { op: 'search', q: q }).then(function(j){ $('cm-sug').innerHTML = (j.items || []).map(function(it){ return '<button type="button" class="row g8 sm" style="text-align:left;padding:8px 10px;border:0;border-bottom:1px solid var(--line);background:var(--card);cursor:pointer" data-cm-add="' + esc(JSON.stringify(it)) + '"><b class="fw5">' + esc(it.name) + '</b><span class="mut">' + esc(it.sub) + '</span></button>'; }).join(''); }); }, 200); });
  document.addEventListener('click', function(e){ var b;
    if ((b = e.target.closest('[data-cm-add]'))) { var it = JSON.parse(b.getAttribute('data-cm-add')); if (!picked.some(function(p){ return p.id === it.id; })) picked.push(it); $('cm-sug').innerHTML = ''; $('cm-q').value = ''; chips(); }
    else if ((b = e.target.closest('[data-cm-rm]'))) { picked.splice(+b.getAttribute('data-cm-rm'), 1); chips(); }
    else if ((b = e.target.closest('#cm-ch button'))) { ch = b.getAttribute('data-v'); document.querySelectorAll('#cm-ch button').forEach(function(x){ x.classList.toggle('on', x === b); }); tpls(); prev(); estimate(); }
    else if ((b = e.target.closest('[data-cm-var]'))) { var m = $('cm-msg'), s = m.selectionStart || m.value.length; m.value = m.value.slice(0, s) + b.getAttribute('data-cm-var') + m.value.slice(s); prev(); }
  });
  $('cm-tpl').addEventListener('change', function(){ var t = (TPL[ch] || [])[this.value]; if (!t) return; $('cm-msg').value = t.body; if (t.subject) $('cm-subj').value = t.subject; prev(); });
  ['cm-msg', 'cm-subj'].forEach(function(id){ $(id).addEventListener('input', prev); });
  $('cm-seg').addEventListener('change', estimate); $('cm-list').addEventListener('input', estimate);
  $('cm-test').addEventListener('click', function(){ SL.post('<?= $ajax ?>', data('test')).then(function(j){ SL.toast(j.message || '', !j.success); }); });
  $('cm-form').addEventListener('submit', function(e){ e.preventDefault(); if (!confirm('Send this message now?')) return; var btn = $('cm-send'); btn.disabled = true; $('cm-prog').hidden = false; var tot = { sent: 0, failed: 0, skipped: 0 };
    (function step(after, batch){ var dd = data('send'); dd.after_id = after; dd.batch_id = batch || ''; SL.post('<?= $ajax ?>', dd).then(function(j){ if (!j.success) { SL.toast(j.message || 'Not sent', true); btn.disabled = false; return; } tot.sent += j.sent; tot.failed += j.failed; tot.skipped += j.skipped; var n = tot.sent + tot.failed + tot.skipped; document.querySelector('#cm-prog i').style.width = Math.min(100, Math.round(n / Math.max(1, j.total) * 100)) + '%'; $('cm-progt').textContent = n + ' / ' + j.total + ' · ' + tot.sent + ' sent · ' + tot.failed + ' failed · ' + tot.skipped + ' skipped'; if (j.done) { SL.toast('Finished: ' + tot.sent + ' sent'); btn.disabled = false; } else step(j.after_id, j.batch_id); }).catch(function(){ SL.toast('Network error', true); btn.disabled = false; }); })(0, '');
  });
  tpls(); chips(); prev();
})();
</script>
